                    "sql": "DELETE FROM snitch_db.maplemonk.adherence_warehouse_online WHERE date_timestamp = CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE; INSERT INTO snitch_db.maplemonk.adherence_warehouse_online ( date_timestamp, rule, order_id, sku_list, order_date, final_warehouse,date,ideal_warehouse,available,tags,check1,sku_group,l1_category,category,fit,print_design_mapped,collar_new,material_new,color ) SELECT CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE as \"DATE\", final_output.* FROM ( with incorrect as ( select order_id, sku_list, order_date, final_warehouse, order_date::date as date, ideal_warehouse from snitch_db.maplemonk.speed_analysis where final_warehouse like \'%SAPL%\' and assigned_date >= current_date() -7 and assigned_date <= current_date() and quantity_in_box = 1 ), inventory as ( select date as date2, case when facility like \'%NORTH%\' then \'North\' when facility like \'%SAPL%\' then \'South\' else null end as facility, \"Item SkuCode\", sum(inventory::INTEGER) as available from snitch_db.maplemonk.snitch_final_inventory_wh2 where date >= current_date() -7 and date <= current_date() group by 1, 2, 3 ), final1 as ( select CASE WHEN IFNULL(available, 0) = 0 then \'Inv_NA\' else null end as allocation, * from incorrect i left join inventory q on CONCAT(i.date, i.ideal_warehouse, i.sku_list) = CONCAT(q.date2, facility, q.\"Item SkuCode\") ), tags as ( select order_name, sku, tags, order_timestamp::DATE as date1, CASE WHEN tags like \'%WH1%\' then \'SAPL-WH1\' WHEN tags like \'%WH2%\' then \'SAPL-WH2\' WHEN tags like \'%NORTH%\' then \'SAPL-NORTH-TAURU\' WHEN tags like \'%Exchange%\' then \'Exchange\' WHEN tags like \'%FSC%\' then \'Omni\' else null end as rule from snitch_db.maplemonk.fact_items_snitch where order_timestamp::DATE >= current_date() -7 and order_timestamp::DATE <= current_date() and sku not like \'%EGF-%\' and rule is not null ), final2 as ( select * from final1 f left join tags t on CONCAT(f.order_id, f.sku_list) = CONCAT(t.order_name, t.sku) ), final3 as ( select coalesce(f.allocation, rule) as rule, f.order_id, f.sku_list, f.order_date, f.final_warehouse, f.date, f.ideal_warehouse, f.available, f.tags, CASE WHEN f.ideal_warehouse = \'South\' and f.final_warehouse like \'%SAPL-WH%\' then \'correct\' WHEN f.ideal_warehouse = \'North\' and f.final_warehouse like \'%TAURU%\' then \'correct\' else \'incorrect\' end as check1, u.skugroup sku_group from final2 f left join SNITCH_DB.MAPLEMONK.uc_final_item_master u on f.sku_LIST = u.sku ) select a.*, lower(COALESCE( CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(a.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN ( \'perfumes\', \'accessories\', \'bags\', \'belts\', \'sunglasses\', \'shoes\', \'slip-ons\' ) THEN \'long_tail\' END, CASE WHEN UPPER(a.sku_group) LIKE \'4MSWHC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSWC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSKC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRD%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRT%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' END, \'Snitch\' )) AS l1_category, lower( replace( COALESCE( b.category, CASE WHEN UPPER(a.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(a.sku_group) LIKE \'4MSWC%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(a.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MLXT%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(a.sku_group) LIKE \'4MSS%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(a.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(a.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(a.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(a.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(a.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MSW%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(a.sku_group) LIKE \'4MST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(a.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MBL%\' THEN \'Belts\' END ), \'-\', \'\' ) ) AS category, b.fit AS fit, b.print_design_mapped, b.collar_new, case when lower(b.product_name) like \'%linen%\' then \'linen\' else b.material_new end material_new, CASE WHEN COLOR IS NULL OR TRIM(COLOR) = \'\' THEN \'Others\' WHEN COLOR IN (\'Blue\',\'Navy\',\'Dark Blue\',\'Light Blue\',\'Indigo\') THEN \'Blue\' WHEN COLOR = \'Black\' THEN \'Black\' WHEN COLOR = \'Beige\' THEN \'Beige\' WHEN COLOR IN (\'Dark Green\',\'Green\',\'Light Green\',\'Sage Green\') THEN \'Green\' WHEN COLOR IN (\'Brown\',\'Dark Brown\',\'Light Brown\') THEN \'Brown\' WHEN COLOR IN (\'Grey\',\'Charcoal Grey\',\'Light Grey\',\'Ash Grey\',\'Greyish Blue\') THEN \'Grey\' WHEN COLOR = \'Khaki\' THEN \'Khaki\' WHEN COLOR = \'Olive\' THEN \'Olive\' WHEN COLOR = \'White\' THEN \'White\' ELSE \'Others\' END color, from final3 a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group ) final_output;",
